    /// Serves a `Server` on a connection (pass it in `CapSlot.export`).
    /// Inherited interfaces dispatch here too (the Server protocol inherits
    /// their requirements; E-order holds for the whole closure).
    public struct Export: ExportHandler {
        public let server: any Server
        public init(_ server: any Server) { self.server = server }
        public func handle(_ call: InboundCall, on connection: isolated RPCConnection) async throws -> CallResponse {
            switch call.interfaceID {
            case GameWorld.interfaceID:
                switch call.methodID {
                case GameWorld.Method.spawnEntity.rawValue:
                    let params = try decoding { try GameWorld.SpawnEntityParams.Reader(Message(bytes: call.params).rootStruct()) }
                    let results = try await server.spawnEntity(params: params, caps: call.caps, on: call.connection)
                    return CallResponse(message: results.bytes, caps: results.caps)
                case GameWorld.Method.despawnEntity.rawValue:
                    let params = try decoding { try GameWorld.DespawnEntityParams.Reader(Message(bytes: call.params).rootStruct()) }
                    let results = try await server.despawnEntity(params: params, caps: call.caps, on: call.connection)
                    return CallResponse(message: results.bytes, caps: results.caps)
                case GameWorld.Method.getEntity.rawValue:
                    let params = try decoding { try GameWorld.GetEntityParams.Reader(Message(bytes: call.params).rootStruct()) }
                    let results = try await server.getEntity(params: params, caps: call.caps, on: call.connection)
                    return CallResponse(message: results.bytes, caps: results.caps)
                case GameWorld.Method.moveEntity.rawValue:
                    let params = try decoding { try GameWorld.MoveEntityParams.Reader(Message(bytes: call.params).rootStruct()) }
                    let results = try await server.moveEntity(params: params, caps: call.caps, on: call.connection)
                    return CallResponse(message: results.bytes, caps: results.caps)
                case GameWorld.Method.damageEntity.rawValue:
                    let params = try decoding { try GameWorld.DamageEntityParams.Reader(Message(bytes: call.params).rootStruct()) }
                    let results = try await server.damageEntity(params: params, caps: call.caps, on: call.connection)
                    return CallResponse(message: results.bytes, caps: results.caps)
                case GameWorld.Method.queryArea.rawValue:
                    let params = try decoding { try GameWorld.QueryAreaParams.Reader(Message(bytes: call.params).rootStruct()) }
                    let results = try await server.queryArea(params: params, caps: call.caps, on: call.connection)
                    return CallResponse(message: results.bytes, caps: results.caps)
                default:
                    throw RPCError.unimplemented(reason: "GameWorld: no such method")
                }
            default:
                throw RPCError.unimplemented(reason: "GameWorld: wrong interface")
            }
        }
    }

